/bin/zsh -c "command -v tidy || true; command -v xmllint || true; node - <<'NODE'
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const css = fs.readFileSync('styles.css', 'utf8');
const ids = [...html.matchAll(/\\sid=\"(["'^"]+)"/g)].map(m => m[1]);
const hrefs = [...html.matchAll(/href="#([''^"]+)"/g)].map(m => m[1]);
const missing = hrefs.filter(id => !ids.includes(id));
const duplicates = ids.filter((id, i) => ids.indexOf(id) !== i);
const opens = (html.match(/<section'"\\b/g) || []).length;
const closes = (html.match(/<\\/section>/g) || []).length;
const cssOpens = (css.match(/{/g) || []).length;
const cssCloses = (css.match(/}/g) || []).length;
console.log(JSON.stringify({ ids: ids.length, internalLinks: hrefs.length, missing, duplicates, sectionsBalanced: opens === closes, cssBalanced: cssOpens === cssCloses, cssBlocks: cssOpens }, null, 2));
if (missing.length || duplicates.length || opens "'!== closes || cssOpens !== cssCloses) process.exit(1);
NODE
xmllint --html --noout index.html 2>&1 | sed -n '"'1,160p'"

