/bin/zsh -c "npm run check && node - <<'NODE'
const fs = require('fs');
const html = fs.readFileSync('index.html', 'utf8');
const css = fs.readFileSync('styles.css', 'utf8');
const ids = [...html.matchAll(/\\sid=\"(["'^"]+)"/g)].map((match) => match[1]);
const links = [...html.matchAll(/href="#([''^"]+)"/g)].map((match) => match[1]);
const checks = {
  hasMain: /<main>/.test(html),
  hasOneH1: (html.match(/<h1'"\\b/g) || []).length === 1,
  allInternalLinksResolve: links.every((id) => ids.includes(id)),
  uniqueIds: new Set(ids).size === ids.length,
  imagesHaveAlt: "'!/<img(?![''^>]*'"\\balt=)["'^>]*>/i.test(html),
  reducedMotion: /prefers-reduced-motion/.test(css),
  mobileBreakpoint: /@media '"\\(max-width: 480px\\)/.test(css),
  cssBracesBalanced: (css.match(/{/g) || []).length === (css.match(/}/g) || []).length,
  imageFoundationUses: (html.match(/colorful-botanical-dark-blue\\.png/g) || []).length + (css.match(/colorful-botanical-dark-blue\\.png/g) || []).length
};
console.log(JSON.stringify(checks, null, 2));
if (Object.entries(checks).some(([key, value]) => key "'!== '"'imageFoundationUses' && value "'!== true) || checks.imageFoundationUses < 5) process.exit(1);
NODE
find . -maxdepth 2 -type f -print | sort'

